-- 18 ORIGINAL four-option review-only exercises: 3 per previously empty construct.
-- Source concepts from uploaded ICT 9 (2020), ICT 11 (2021),
-- and Cambridge+ 10-11 chapter 19/4. Not copied from Telegram.
-- Human expert approval required; no published learner items created.
-- DO NOT APPLY TO PRODUCTION until explicit user release permission.
begin;
do $seed_uncovered_review$
declare item jsonb;v_construct uuid;v_subject uuid;v_group text;
  v_lesson uuid;v_question uuid;v_option uuid;v_n int;v_correct int;
begin
 for item in select * from jsonb_array_elements('[{"code":"S3.ALGO.03","ref":"authored:zero-construct-y1:20261012:S3.ALGO.03:01","source":"ICT 9-sinf 2020 III-bob Algoritmlash asoslari","slug":"m06-03","stem":"To‘g‘ri to‘rtburchak tomonlari a va b kiritilgach, yuzani hisoblash algoritmi qaysi ketma-ketlikda to‘g‘ri tuzilgan?","options":["Boshlash → S=a×b → a,b ni kiritish → chiqarish → Tugatish","Boshlash → a,b ni kiritish → S=a×b → S ni chiqarish → Tugatish","Boshlash → S ni chiqarish → a,b ni kiritish → S=a×b → Tugatish","Boshlash → a,b ni kiritish → natijani chiqarish → hisoblash → Tugatish"],"correct":1,"explanation":"Avval kirish qiymatlari olinadi, keyin S=a×b hisoblanadi, so‘ng natija chiqariladi.","cognitive":"qollash","difficulty":3},{"code":"S3.ALGO.03","ref":"authored:zero-construct-y1:20261012:S3.ALGO.03:02","source":"ICT 9-sinf 2020 III-bob Algoritmlash asoslari","slug":"m06-03","stem":"Ikkita butun a va b sonidan kattasini chiqarish algoritmi uchun qaysi tarmoqlanish mos?","options":["Agar a≥b bo‘lsa a ni, aks holda b ni chiqarish","Agar a≥b bo‘lsa b ni, aks holda a ni chiqarish","Doimo a+b yig‘indisini chiqarish","Faqat a=b bo‘lganda natija chiqarish"],"correct":0,"explanation":"a≥b bo‘lsa katta qiymat a; aks holda b. Teng qiymatlar ham a orqali to‘g‘ri qaytariladi.","cognitive":"qollash","difficulty":3},{"code":"S3.ALGO.03","ref":"authored:zero-construct-y1:20261012:S3.ALGO.03:03","source":"ICT 9-sinf 2020 III-bob Algoritmlash asoslari","slug":"m06-03","stem":"Uchta sonning o‘rtacha arifmetigini hisoblash algoritmida qaysi amal natijadan oldin bajarilishi shart?","options":["Eng katta sonni avtomatik tanlash","Sonlarning ko‘paytmasini 3 ga bo‘lish","Uchta sonni qo‘shib, yig‘indini 3 ga bo‘lish","Har bir sondan 3 ni ayirish"],"correct":2,"explanation":"O‘rtacha arifmetik (a+b+c)/3. Natijani chiqarishdan oldin yig‘indi va bo‘lish bajarilishi kerak.","cognitive":"qollash","difficulty":3},{"code":"S3.LOGIC.01","ref":"authored:zero-construct-y1:20261012:S3.LOGIC.01:01","source":"ICT 9-sinf 2020 I-bob Mantiqiy mulohazalar","slug":"m04-01","stem":"Quyidagi jumlalardan qaysi biri ikki sodda mulohazadan tuzilgan murakkab mulohaza?","options":["7 soni tub son","8 soni juft va 3 soni toq","12 soni uchga bo‘linadi","Toshkent O‘zbekiston poytaxti"],"correct":1,"explanation":"Ikki mustaqil tasdiq VA mantiqiy bog‘lovchisi bilan birlashtirilgan; qolganlari bittadan sodda mulohazadir.","cognitive":"bilish","difficulty":2},{"code":"S3.LOGIC.01","ref":"authored:zero-construct-y1:20261012:S3.LOGIC.01:02","source":"ICT 9-sinf 2020 I-bob Mantiqiy mulohazalar","slug":"m04-01","stem":"‘6 soni juft’ mulohazasining inkori qaysi?","options":["6 soni juft emas","6 soni juft yoki toq","6 soni 2 ga bo‘linadi","6 soni 3 ga bo‘linadi"],"correct":0,"explanation":"Mulohazaning inkori uning rostlik qiymatini teskari qiladi: ‘6 juft’ rost, ‘6 juft emas’ yolg‘on.","cognitive":"bilish","difficulty":2},{"code":"S3.LOGIC.01","ref":"authored:zero-construct-y1:20261012:S3.LOGIC.01:03","source":"ICT 9-sinf 2020 I-bob Mantiqiy mulohazalar","slug":"m04-01","stem":"‘Bugun yomg‘ir yog‘adi yoki havo sovuq bo‘ladi’ mulohazasi qanday tuzilgan?","options":["Faqat bitta sodda mulohaza","Ikkita sodda mulohaza VA bilan bog‘langan","Ikkita sodda mulohaza YOKI bilan bog‘langan","Hech qanday rostlik qiymati bo‘lmaydigan buyruq"],"correct":2,"explanation":"Yomg‘ir yog‘ishi va havo sovuq bo‘lishi alohida mulohazalar; ular YOKI bog‘lovchisi bilan murakkab mulohaza hosil qiladi.","cognitive":"bilish","difficulty":2},{"code":"S3.LOGIC.03","ref":"authored:zero-construct-y1:20261012:S3.LOGIC.03:01","source":"ICT 9-sinf 2020 I-bob Mantiqiy amallar va xulosa","slug":"m04-03","stem":"P rost, Q yolg‘on bo‘lsa, P VA (Q EMAS) ifodasining qiymati nima?","options":["Rost, chunki Q EMAS rost va P ham rost","Yolg‘on, chunki Q yolg‘on","Yolg‘on, chunki inkor doimo yolg‘on","Rost emas, chunki P va Q turli qiymatli"],"correct":0,"explanation":"Q yolg‘on bo‘lsa NOT Q rost; P ham rost, demak P AND NOT Q rost.","cognitive":"qollash","difficulty":3},{"code":"S3.LOGIC.03","ref":"authored:zero-construct-y1:20261012:S3.LOGIC.03:02","source":"ICT 9-sinf 2020 I-bob Mantiqiy amallar va xulosa","slug":"m04-03","stem":"Ali Validdan baland, Vali esa Ra’nodan baland. Qaysi mantiqiy xulosa albatta to‘g‘ri?","options":["Ra’no Alidan baland","Ali Ra’nodan baland","Ali bilan Ra’noning bo‘yi teng","Vali bilan Ali bo‘yi teng"],"correct":1,"explanation":"Balandlik munosabati tranzitiv: Ali>Vali va Vali>Ra’no bo‘lsa, Ali>Ra’no.","cognitive":"mulohaza","difficulty":3},{"code":"S3.LOGIC.03","ref":"authored:zero-construct-y1:20261012:S3.LOGIC.03:03","source":"ICT 9-sinf 2020 I-bob Mantiqiy amallar va xulosa","slug":"m04-03","stem":"P yolg‘on va Q rost bo‘lganda (P YOKI Q) VA (P EMAS) qiymati nima?","options":["Yolg‘on, chunki P yolg‘on","Rost, chunki ikkala qism ham rost","Yolg‘on, chunki Q rost","Qiymati aniqlanmaydi"],"correct":1,"explanation":"P OR Q rost, chunki Q rost. NOT P ham rost; ikkisi AND bilan bog‘langani uchun umumiy ifoda rost.","cognitive":"qollash","difficulty":3},{"code":"S4.CODE.04","ref":"authored:zero-construct-y1:20261012:S4.CODE.04:01","source":"Cambridge+ 10-11-sinf 19-bob 19.01 JavaScript","slug":"javascript-sintaksisi-m08-11-draft","stem":"JavaScript kodi qanday qiymat chiqaradi? let x = 4; x = x + 3; console.log(x);","options":["4, chunki x dastlab 4 edi","3, chunki faqat qo‘shilgan son chiqadi","7, chunki x yangilanadi","43, chunki sonlar matn kabi ulanadi"],"correct":2,"explanation":"x=x+3 bajarilgach x=7 bo‘ladi; console.log aynan shu qiymatni konsolga chiqaradi.","cognitive":"qollash","difficulty":3},{"code":"S4.CODE.04","ref":"authored:zero-construct-y1:20261012:S4.CODE.04:02","source":"Cambridge+ 10-11-sinf 19-bob 19.01 JavaScript","slug":"javascript-sintaksisi-m08-11-draft","stem":"JavaScript ifodasi console.log(3 + 2 * 4) qanday natija chiqaradi?","options":["20, chunki oldin qo‘shiladi","14, chunki amallar chapdan o‘ngga bajariladi","11, chunki oldin ko‘paytirish bajariladi","24, chunki barcha sonlar ko‘paytiriladi"],"correct":2,"explanation":"2*4=8 hisoblanadi, keyin 3+8=11; operatorlar ustuvorligi amal qiladi.","cognitive":"qollash","difficulty":3},{"code":"S4.CODE.04","ref":"authored:zero-construct-y1:20261012:S4.CODE.04:03","source":"Cambridge+ 10-11-sinf 19-bob 19.01 JavaScript","slug":"javascript-sintaksisi-m08-11-draft","stem":"HTML hujjat ichida JavaScript buyruqlari qaysi tegga joylashtiriladi?","options":["<style> ... </style>","<script> ... </script>","<table> ... </table>","<title> ... </title>"],"correct":1,"explanation":"JavaScript kodi odatda script elementi orqali HTML hujjatiga kiritiladi; style esa CSS uchun.","cognitive":"bilish","difficulty":2},{"code":"S6.NET.02","ref":"authored:zero-construct-y1:20261012:S6.NET.02:01","source":"ICT 11-sinf 2021 26-dars Tarmoq topologiyasi","slug":"m12-03","stem":"Barcha kompyuterlar markaziy kommutatorga ulangan tarmoq qaysi topologiyaga mos?","options":["Shina (bus)","Halqa (ring)","Yulduz (star)","To‘liq ulanishli mesh"],"correct":2,"explanation":"Yulduz topologiyasida har bir tugun markaziy switch yoki hubga alohida ulanish orqali bog‘lanadi.","cognitive":"bilish","difficulty":2},{"code":"S6.NET.02","ref":"authored:zero-construct-y1:20261012:S6.NET.02:02","source":"ICT 11-sinf 2021 26-dars Tarmoq topologiyasi","slug":"m12-03","stem":"Yulduz topologiyali lokal tarmoqda markaziy kommutator ishdan chiqsa, odatda nima sodir bo‘ladi?","options":["Tugunlar avtomatik halqa hosil qiladi","Markaziy aloqa to‘xtab, ko‘p tugunlar bog‘lanmay qoladi","Barcha kompyuterlar internetga tezroq ulanadi","Faqat bitta tasodifiy printer zarar ko‘radi"],"correct":1,"explanation":"Yulduz topologiyada markaziy qurilma yagona uzilish nuqtasi bo‘lishi mumkin.","cognitive":"mulohaza","difficulty":3},{"code":"S6.NET.02","ref":"authored:zero-construct-y1:20261012:S6.NET.02:03","source":"ICT 11-sinf 2021 26-dars Tarmoq topologiyasi","slug":"m12-03","stem":"Bir xil umumiy magistral kabelga ulangan kompyuterlar qaysi topologiyada ishlaydi?","options":["Shina (bus)","Yulduz (star)","Halqa (ring)","Daraxtning faqat simsiz varianti"],"correct":0,"explanation":"Shina topologiyasida barcha qurilmalar umumiy aloqa segmentidan foydalanadi.","cognitive":"bilish","difficulty":2},{"code":"S6.NET.04","ref":"authored:zero-construct-y1:20261012:S6.NET.04:01","source":"Cambridge+ 10-11-sinf 4-bob Internet xavfsizligi","slug":"m12-06","stem":"‘Akkauntingiz yopiladi, darhol parolingizni quyidagi havolada kiriting’ degan shubhali email kelsa, eng xavfsiz harakat qaysi?","options":["Xatdagi havolani ochib parolni kiritish","Havolani guruhdagilarga yuborish","Xatni ishonchsiz deb hisoblab, xizmatning rasmiy manzilini mustaqil ochib tekshirish","Parolni xatga javoban yuborish"],"correct":2,"explanation":"Phishing xati bosim va shoshiltirishdan foydalanishi mumkin; rasmiy saytga mustaqil kirib holatni tekshirish xavfsizroq.","cognitive":"qollash","difficulty":3},{"code":"S6.NET.04","ref":"authored:zero-construct-y1:20261012:S6.NET.04:02","source":"Cambridge+ 10-11-sinf 4-bob Internet xavfsizligi","slug":"m12-06","stem":"Ijtimoiy tarmoqda notanish profil shaxsiy telefon, manzil va bir martalik tasdiqlash kodini so‘radi. To‘g‘ri qaror qaysi?","options":["Hamma ma’lumotni yuborish, chunki profil rasmi bor","Faqat bir martalik kodni yuborish","Shaxsiy ma’lumot va tasdiqlash kodini bermasdan hisobni himoyalash","Manzilni ochiq postga joylash"],"correct":2,"explanation":"Shaxsiy ma’lumot va bir martalik kodni notanish shaxsga berish hisobni egallash xavfini oshiradi.","cognitive":"qollash","difficulty":3},{"code":"S6.NET.04","ref":"authored:zero-construct-y1:20261012:S6.NET.04:03","source":"Cambridge+ 10-11-sinf 4-bob Internet xavfsizligi","slug":"m12-06","stem":"Ommaviy Wi-Fi tarmog‘ida maxfiy hisobga kirish zarur bo‘lsa, qaysi yondashuv eng xavfsiz?","options":["Noma’lum Wi-Fi tarmog‘ida barcha himoyani o‘chirish","Imkon bo‘lsa ishonchli mobil tarmoqdan foydalanib, rasmiy HTTPS manzilni tekshirish","Parolni brauzer oynasida boshqalarga ko‘rsatib yozish","Noma’lum sertifikat ogohlantirishlarini e’tiborsiz qoldirish"],"correct":1,"explanation":"Noishonchli ommaviy tarmoq o‘rniga ishonchli ulanishni tanlash va sayt identifikatorini tekshirish xavfni kamaytiradi.","cognitive":"mulohaza","difficulty":3}]'::jsonb)
 loop
  if exists(select 1 from public.questions
    where source_reference like (item->>'ref')||'|%') then continue;end if;
  select c.id,c.subject_id,c.group_code into strict v_construct,v_subject,v_group
  from public.constructs c where c.code=item->>'code' and c.is_active;

  select l.id into v_lesson from public.lessons l
  join public.lesson_constructs lc on lc.lesson_id=l.id
  where lc.construct_id=v_construct
    and l.status in ('review'::public.content_status,'published'::public.content_status)
    and (item->>'code'<>'S4.CODE.04' or l.slug=item->>'slug')
  order by
    case when l.slug=item->>'slug' then 0 else 1 end,
    case when l.slug ~ '^m[0-9]{2}-' then 1 else 0 end,
    l.order_idx, l.id
  limit 1;
  if v_lesson is null then
    raise exception 'No lesson mapped to review source construct: %',item->>'code';
  end if;

  if jsonb_array_length(item->'options')<>4 or (item->>'correct')::int not between 0 and 3 then
    raise exception 'Invalid authored question choice shape: %',item->>'ref';
  end if;
  v_question:=gen_random_uuid();
  insert into public.questions (
    id,subject_id,construct_id,group_code,format,cognitive,difficulty,
    stem_md,is_generated,status,source_reference,source_lesson_id
  )values (
    v_question,v_subject,v_construct,v_group,
    'Y1'::public.question_format,
    (item->>'cognitive')::public.cognitive_level,(item->>'difficulty')::int,
    item->>'stem',false,'review'::public.content_status,
    (item->>'ref')||'|source:'||(item->>'source'),v_lesson
  );
  v_correct:=(item->>'correct')::int;
  for v_n in 0..3 loop
    v_option:=gen_random_uuid();
    insert into public.question_options(question_id,id,content_md,order_idx)
    values(v_question,v_option,item->'options'->>v_n,v_n);
    if v_n=v_correct then
      insert into public.question_keys(question_id,payload,explanation_md)
      values(v_question,jsonb_build_object('correct_option_id',v_option),item->>'explanation');
    end if;
  end loop;
 end loop;
end
$seed_uncovered_review$;
commit;